{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(node) {
  return [...node.m.keys()].sort(cmp)
}

function scalarJson(node) {
  switch (node.t) {
    case 'string': return JSON.stringify(node.v)
    case 'integer': return node.v
    case 'float': return JSON.stringify(node.v)
    default: return String(node.v)
  }
}

function render(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  if (node.t === 'table') {
    const keys = sortedKeys(node)
    if (!keys.length) return '{}'
    const parts = keys.map((k) => `${pad}${JSON.stringify(k)}: ${render(node.m.get(k), indent + 1)}`)
    return `{\n${parts.join(',\n')}\n${end}}`
  }
  if (node.t === 'array') {
    if (!node.items.length) return '[]'
    const parts = node.items.map((n) => pad + render(n, indent + 1))
    return `[\n${parts.join(',\n')}\n${end}]`
  }
  return scalarJson(node)
}

export function toJson(root) {
  return render(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === '' ? k : `${path}.${k}`
        const c = node.m.get(k)
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, '')
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

